CREATE TABLE IF NOT EXISTS gis_authoritative_acquisition_runs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version TEXT NOT NULL,provider TEXT NOT NULL,dataset_name TEXT NOT NULL,source_url TEXT,status TEXT NOT NULL DEFAULT 'STARTED',started_at TIMESTAMPTZ NOT NULL DEFAULT now(),completed_at TIMESTAMPTZ,features_examined INTEGER DEFAULT 0,features_imported INTEGER DEFAULT 0,error_count INTEGER DEFAULT 0,notes JSONB NOT NULL DEFAULT '{}'::jsonb);
CREATE TABLE IF NOT EXISTS gis_geometry_sources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),provider TEXT NOT NULL,dataset_name TEXT NOT NULL,dataset_version TEXT,source_url TEXT,geometry_format TEXT,geometry_crs TEXT,feature_count INTEGER,provenance JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'REGISTERED',imported_at TIMESTAMPTZ,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(provider,dataset_name,dataset_version));
CREATE TABLE IF NOT EXISTS gis_geometry_features (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),source_id UUID NOT NULL REFERENCES gis_geometry_sources(id),provider TEXT NOT NULL,feature_id TEXT NOT NULL,feature_name TEXT,state_code TEXT,parent_feature_id TEXT,geometry_wkt TEXT,geometry_geojson JSONB,normalized_geometry_available BOOLEAN NOT NULL DEFAULT false,geometry_valid BOOLEAN,geometry_empty BOOLEAN,source_srid TEXT,normalized_srid TEXT,validation_metadata JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(source_id,feature_id));
CREATE TABLE IF NOT EXISTS gis_spatial_identity_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version TEXT NOT NULL,source_feature_id TEXT NOT NULL,target_feature_id TEXT NOT NULL,source_provider TEXT NOT NULL,target_provider TEXT NOT NULL,source_geometry_valid BOOLEAN,target_geometry_valid BOOLEAN,source_area DOUBLE PRECISION,target_area DOUBLE PRECISION,intersection_area DOUBLE PRECISION,source_overlap_ratio DOUBLE PRECISION,target_overlap_ratio DOUBLE PRECISION,iou DOUBLE PRECISION,centroid_distance DOUBLE PRECISION,bbox_overlap DOUBLE PRECISION,name_similarity DOUBLE PRECISION,state_match BOOLEAN,spatial_score DOUBLE PRECISION,identity_score DOUBLE PRECISION,combined_score DOUBLE PRECISION,confidence TEXT,decision TEXT,evidence JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(crosswalk_version,source_feature_id,target_feature_id));
CREATE TABLE IF NOT EXISTS gis_spatial_intersection_evidence (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version TEXT NOT NULL,source_feature_id TEXT NOT NULL,target_feature_id TEXT NOT NULL,source_provider TEXT NOT NULL,target_provider TEXT NOT NULL,source_geometry_available BOOLEAN NOT NULL DEFAULT false,target_geometry_available BOOLEAN NOT NULL DEFAULT false,intersection_area DOUBLE PRECISION,source_area DOUBLE PRECISION,target_area DOUBLE PRECISION,source_overlap_ratio DOUBLE PRECISION,target_overlap_ratio DOUBLE PRECISION,iou DOUBLE PRECISION,geometry_method TEXT,geometry_crs TEXT,evidence_status TEXT NOT NULL DEFAULT 'REQUIRES_GEOMETRY',confidence TEXT NOT NULL DEFAULT 'UNRESOLVED',evidence JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(crosswalk_version,source_feature_id,target_feature_id));
CREATE TABLE IF NOT EXISTS gis_identity_resolution_results (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version TEXT NOT NULL,source_feature_id TEXT NOT NULL,target_feature_id TEXT NOT NULL,spatial_iou DOUBLE PRECISION,source_overlap_ratio DOUBLE PRECISION,target_overlap_ratio DOUBLE PRECISION,identity_score DOUBLE PRECISION,combined_score DOUBLE PRECISION,confidence TEXT NOT NULL DEFAULT 'UNRESOLVED',decision TEXT NOT NULL DEFAULT 'UNRESOLVED',rationale JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(crosswalk_version,source_feature_id,target_feature_id));
CREATE TABLE IF NOT EXISTS gis_evidence_acquisition_queue (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),crosswalk_version TEXT NOT NULL,source_feature_id TEXT NOT NULL,priority TEXT NOT NULL DEFAULT 'HIGH',missing_evidence TEXT,required_source_providers TEXT,missing_geometry BOOLEAN NOT NULL DEFAULT true,missing_intersection BOOLEAN NOT NULL DEFAULT true,missing_identity_evidence BOOLEAN NOT NULL DEFAULT false,required_provider TEXT,required_dataset TEXT,required_evidence JSONB NOT NULL DEFAULT '{}'::jsonb,status TEXT NOT NULL DEFAULT 'OPEN',resolution_blocker TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(crosswalk_version,source_feature_id));
CREATE INDEX IF NOT EXISTS idx_gis_geometry_features_provider_feature ON gis_geometry_features(provider,feature_id);
CREATE INDEX IF NOT EXISTS idx_gis_spatial_identity_version_source ON gis_spatial_identity_evidence(crosswalk_version,source_feature_id);
CREATE INDEX IF NOT EXISTS idx_gis_identity_resolution_version_source ON gis_identity_resolution_results(crosswalk_version,source_feature_id);